# Regenerates AGENT_ROLES_AND_DECISION_RIGHTS.md from roles/agent-roles.json and decision-rights.json.
import json,os
os.chdir(os.path.dirname(os.path.abspath(__file__)))
cat=json.load(open('roles/agent-roles.json')); dr=json.load(open('decision-rights.json'))
md=["---","type: reference","source: machine","created: "+cat["updated"],"ai-model: claude-opus-5.5","generated-from: roles/agent-roles.json, decision-rights.json","tags: [venture-template, roles, agents, decision-rights]","---","","# Agent roles and decision rights","","*Generated by `render-roles.py`. Decided in "+cat["governed_by"]+". Roles are templates; entities instantiate positions ([[position-schema]]).*","","## Roles","","| Role | Occupant | Model tier | Decides | Research | Reviews | Escalates to |","|---|---|---|---|---|---|---|"]
for r in cat["roles"]: md.append("| **%s** | %s | %s | %s | %s | %s | %s |"%(r['name'],r['occupant'],r['tier'],'; '.join(r['decides']),r['research'],r['reviews'],r['escalates_to'] or '—'))
md+=["",cat["conformance"],"","## Decision rights (template)","","| Class | Owner | Level | Condition |","|---|---|---|---|"]
for c in dr["classes"]: md.append("| %s | %s | **%s** | %s |"%(c['description'],c['owner'],c['level'],c.get('condition','')))
md+=["","Levels: "+"; ".join("**%s**: %s"%(k,v) for k,v in dr["levels"].items())]
open('AGENT_ROLES_AND_DECISION_RIGHTS.md','w').write("\n".join(md)+"\n")
print(len(cat["roles"]),"roles;",len(dr["classes"]),"classes")
